//! TypeScript binding generation.
//!
//! `cargo test -p orkestr-protocol export_bindings` runs every ts-rs
//! auto-generated `export_bindings_*` test of this crate **and** the explicit
//! [`export_bindings`] test below, which
//! 1. exports every domain entity (they live in another crate, so their own
//!    auto tests do not run here), and
//! 2. writes `methods.ts` — the typed `Methods` map generated from
//!    [`crate::methods::registry`].
//!
//! Output dir: `TS_RS_EXPORT_DIR` (set in `.cargo/config.toml` to
//! `packages/protocol/src/generated`).

use std::fmt::Write as _;
use std::path::Path;

use ts_rs::{Config, TS};

use crate::methods::registry;

fn export_domain(cfg: &Config) {
    use orkestr_domain::*;
    macro_rules! all {
        ($($t:ty),* $(,)?) => { $( <$t as TS>::export_all(cfg).expect(stringify!($t)); )* };
    }
    all!(
        User,
        Device,
        Node,
        Project,
        Repository,
        Workspace,
        WorkspaceSnapshot,
        Provider,
        ProviderCredentialReference,
        Model,
        AgentTemplate,
        AgentInstance,
        AgentTeam,
        Task,
        TaskDependency,
        Execution,
        ToolCall,
        Approval,
        MemoryItem,
        KnowledgeSource,
        Decision,
        Environment,
        Deployment,
        SecretReference,
        UsageRecord,
        AuditEvent,
        Plugin,
        McpServer,
        Notification,
        AgentState,
        Capability,
        ApprovalMode,
        TaskStatus,
        TaskPriority,
        PermissionRule,
        ProviderHealth,
        AuthState,
        Budget,
        UsageSummary,
        ModelRef,
        RiskLevel,
        Actor,
        SessionId,
        CorrelationId,
        TerminalId,
        EventId,
    );
}

fn export_protocol(cfg: &Config) {
    use crate::event::*;
    use crate::frames::*;
    use crate::ui_config::*;
    macro_rules! all {
        ($($t:ty),* $(,)?) => { $( <$t as TS>::export_all(cfg).expect(stringify!($t)); )* };
    }
    all!(
        ClientFrame,
        ServerFrame,
        ResFrame,
        AuthResult,
        SubResult,
        ClientInfo,
        crate::RpcError,
        crate::RpcErrorCode,
        Event,
        EventKind,
        UiConfig,
        UiConfigIssue,
        crate::ui_theme::ThemeFile,
        crate::ui_theme::ContrastCheck,
        crate::ui_theme::TokenKind,
        crate::ui_theme::Rgba,
        StopReason,
        LogLevel,
        EmergencyScope,
        RollbackScope,
        FileChangeKind,
        MessageRole,
    );
}

fn module_path(path: &Path) -> String {
    let s = path.with_extension("").to_string_lossy().replace('\\', "/");
    format!("./{s}")
}

fn write_methods_ts(cfg: &Config) {
    let methods = registry();
    let mut imports = std::collections::BTreeMap::<String, String>::new();
    let mut body = String::new();
    for m in &methods {
        (m.export)(cfg).expect(m.name);
        for (name, path) in [((m.params_ts)(cfg), (m.params_path)()), ((m.result_ts)(cfg), (m.result_path)())] {
            if let Some(path) = path {
                imports.insert(name, module_path(&path));
            }
        }
        let _ = writeln!(body, "  \"{}\": [{}, {}];", m.name, (m.params_ts)(cfg), (m.result_ts)(cfg));
    }
    let mut out = String::from(
        "// This file was generated by orkestr-protocol (export_bindings). Do not edit this file manually.\n",
    );
    for (name, path) in &imports {
        let _ = writeln!(out, "import type {{ {name} }} from \"{path}\";");
    }
    out.push_str("\n/** Typed RPC method map: `\"area.verb\": [Params, Result]`. */\nexport type Methods = {\n");
    out.push_str(&body);
    out.push_str("};\n\n/** All implemented method names. */\nexport const METHOD_NAMES = [\n");
    for m in &methods {
        let _ = writeln!(out, "  \"{}\",", m.name);
    }
    out.push_str("] as const;\n\n");
    let _ = writeln!(
        out,
        "/** Wire protocol version (see orkestr-protocol PROTOCOL_VERSION). */\nexport const PROTOCOL_VERSION = {};",
        crate::PROTOCOL_VERSION
    );
    let _ = writeln!(
        out,
        "\n/** All event kind names, in declaration order. */\nexport const EVENT_KINDS = [\n{}] as const;",
        crate::event::EventKind::NAMES.iter().map(|k| format!("  \"{k}\",\n")).collect::<String>()
    );
    let _ = writeln!(
        out,
        "\n/** UI config schema version (see orkestr-protocol ui_config). */\nexport const UI_CONFIG_SCHEMA_VERSION = {};
/** Oldest UI config schema version still accepted (upgraded on read). */
export const UI_CONFIG_MIN_SCHEMA_VERSION = {};",
        crate::ui_config::UI_CONFIG_SCHEMA_VERSION,
        crate::ui_config::UI_CONFIG_MIN_SCHEMA_VERSION
    );
    let dir = cfg.out_dir();
    std::fs::create_dir_all(dir).expect("create export dir");
    std::fs::write(dir.join("methods.ts"), out).expect("write methods.ts");
}

/// Writes `themeSchema.ts`: the theme constants, token catalogue, contrast
/// rules, base colors and built-in themes, so `@orkestr/ui` validates with
/// exactly the data the core uses (Phase 3 theme engine).
fn write_theme_schema_ts(cfg: &Config) {
    use crate::ui_theme as th;
    let json = |v: serde_json::Value| serde_json::to_string_pretty(&v).expect("json");
    let catalogue: serde_json::Map<String, serde_json::Value> =
        th::TOKEN_CATALOGUE.iter().map(|(n, k)| ((*n).to_owned(), serde_json::to_value(k).expect("kind"))).collect();
    let rules: Vec<serde_json::Value> = th::CONTRAST_RULES
        .iter()
        .map(|(id, fg, bg, min, hard)| serde_json::json!({ "id": id, "fg": fg, "bg": bg, "min": min, "hard": hard }))
        .collect();
    let base = |t: &[(&str, &str)]| -> serde_json::Value {
        t.iter().map(|(k, v)| ((*k).to_owned(), serde_json::Value::from(*v))).collect::<serde_json::Map<_, _>>().into()
    };
    let mut out = String::from(
        "// This file was generated by orkestr-protocol (export_bindings). Do not edit this file manually.\n\
         import type { ThemeConfig } from \"./ThemeConfig\";\nimport type { TokenKind } from \"./TokenKind\";\n\n",
    );
    let _ = writeln!(
        out,
        "/** Theme exchange format version. */\nexport const THEME_SCHEMA_VERSION = {};",
        th::THEME_SCHEMA_VERSION
    );
    let _ = writeln!(
        out,
        "/** `format` of exported theme files. */\nexport const THEME_FILE_FORMAT = \"{}\";",
        th::THEME_FILE_FORMAT
    );
    let _ = writeln!(out, "/** Max user themes. */\nexport const MAX_USER_THEMES = {};", th::MAX_USER_THEMES);
    let _ = writeln!(out, "/** Max sound mappings. */\nexport const MAX_SOUND_EVENTS = {};", th::MAX_SOUND_EVENTS);
    let _ = writeln!(
        out,
        "/** Max background colors. */\nexport const MAX_BACKGROUND_COLORS = {};",
        th::MAX_BACKGROUND_COLORS
    );
    let _ = writeln!(out, "/** Max tokens per theme. */\nexport const MAX_TOKENS = {};", crate::ui_config::MAX_TOKENS);
    let _ = writeln!(
        out,
        "/** Max token value length. */\nexport const MAX_TOKEN_VALUE_LEN = {};",
        crate::ui_config::MAX_TOKEN_VALUE_LEN
    );
    let _ = writeln!(
        out,
        "\n/** Known tokens and their grammar. */\nexport const TOKEN_CATALOGUE: Readonly<Record<string, TokenKind>> = {};",
        json(catalogue.into())
    );
    let _ = writeln!(
        out,
        "\n/** WCAG contrast rules (`hard` failures make a theme invalid). */\nexport const CONTRAST_RULES: ReadonlyArray<{{ id: string; fg: string; bg: string; min: number; hard: boolean }}> = {};",
        json(rules.into())
    );
    let _ = writeln!(
        out,
        "\n/** Base values of contrast-relevant tokens per mode (tokens.css). */\nexport const BASE_COLORS: {{ Dark: Readonly<Record<string, string>>; Light: Readonly<Record<string, string>> }} = {};",
        json(serde_json::json!({ "Dark": base(th::BASE_DARK), "Light": base(th::BASE_LIGHT) }))
    );
    let _ = writeln!(
        out,
        "\n/** Built-in themes (Nebula first = default). */\nexport const BUILTIN_THEME_LIST: readonly ThemeConfig[] = {};",
        json(serde_json::to_value(th::builtin_themes()).expect("themes"))
    );
    let dir = cfg.out_dir();
    std::fs::create_dir_all(dir).expect("create export dir");
    std::fs::write(dir.join("themeSchema.ts"), out).expect("write themeSchema.ts");
}

#[test]
fn export_bindings() {
    let cfg = Config::from_env();
    export_domain(&cfg);
    export_protocol(&cfg);
    write_methods_ts(&cfg);
    write_theme_schema_ts(&cfg);
}
